const ctx=$items('When Executed by Another Workflow')[0].json;
const tz='Europe/Moscow';
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:tz}).format(new Date());

// IMPORTANT: this formatter receives router data. Read meal rows from the DB node explicitly.
const all=$items('CMD TODAY exact DB')
  .map(i=>i.json)
  .filter(r=>r&&r.id&&r.deleted!==true);
const rows=all.filter(r=>String(r.eaten_day||'').slice(0,10)===today);

const n=v=>Number(v||0), r0=v=>Math.round(n(v)), r1=v=>Math.round(n(v)*10)/10;
const tm=v=>new Intl.DateTimeFormat('ru-RU',{timeZone:tz,hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const clean=s=>String(s||'Еда').replace(/[*_`[\]]/g,'').trim();
const sum=a=>a.reduce((s,x)=>(s.k+=n(x.kcal),s.p+=n(x.prot),s.f+=n(x.fat),s.c+=n(x.carb),s),{k:0,p:0,f:0,c:0});

function sessions(a){
 const s=[...a].sort((x,y)=>new Date(x.eaten_at)-new Date(y.eaten_at)),out=[];
 for(const x of s){
   const p=out.at(-1),t=+new Date(x.eaten_at);
   if(p&&t-(+new Date(p.at))<=12*60*1000){p.rows.push(x);p.at=x.eaten_at}
   else out.push({at:x.eaten_at,rows:[x]});
 }
 return out;
}
function names(a){
 const u=[...new Set(a.map(x=>clean(x.dish)).filter(Boolean))];
 return u.length>2?`${u.slice(0,2).join(', ')} +${u.length-2}`:u.join(', ');
}

const T=sum(rows),S=sessions(rows);
let text=`📊 *Сегодня — текущий статус*\n\n🔥 *${r0(T.k)} ккал*\n🥩 Б ${r1(T.p)} · 🥑 Ж ${r1(T.f)} · 🍚 У ${r1(T.c)}`;
text+=`\n\n🍽 *${S.length} ${S.length===1?'приём':S.length>=2&&S.length<=4?'приёма':'приёмов'}*`;
if(S.length) text+='\n'+S.slice(-6).map(s=>`${tm(s.at)} · ${names(s.rows)} · ${r0(sum(s.rows).k)} ккал`).join('\n');
else text+='\nПитание пока не добавлено.';
return [{json:{chat_id:Number(ctx.chat_id),text}}];

const ctx=$items('When Executed by Another Workflow')[0].json;
const n=v=>Number(v||0), r0=v=>Math.round(n(v)), r1=v=>Math.round(n(v)*10)/10;
const clean=s=>String(s??'').replace(/[*_`[\]]/g,'').trim();
const p=$items('CMD DB profile')[0]?.json||{};
const s=$items('CMD DB settings')[0]?.json||{};
const pt=n(s.protein_target_g||s.protein_target||s.prot_target);
const ft=n(s.fat_target_g||s.fat_target);
const ct=n(s.carb_target_g||s.carb_target);
const kt=n(s.kcal_target||s.target_kcal||s.calories_target);
const cw=n(s.current_weight_kg||p.current_weight_kg), tw=n(s.target_weight_kg||p.target_weight_kg);

let text=`👤 *${clean(p.first_name||'Профиль')}*`;
if(p.username) text+=`\n@${clean(p.username)}`;
text+=`\n\n🎯 ${clean(s.goal||'Цель не указана')}`;
if(cw||tw){
  text+='\n';
  if(cw) text+=`\n⚖️ ${r1(cw)} кг`;
  if(tw) text+=` → ${r1(tw)} кг`;
}
if(s.height_cm) text+=`\n📏 ${r1(s.height_cm)} см`;

if(kt||pt||ft||ct){
  text+='\n\n*Дневная цель*';
  if(kt) text+=`\n🔥 ${r0(kt)} ккал`;
  const macros=[];
  if(pt) macros.push(`Б ${r1(pt)} г`);
  if(ft) macros.push(`Ж ${r1(ft)} г`);
  if(ct) macros.push(`У ${r1(ct)} г`);
  if(macros.length) text+=`\n🥩 ${macros.join(' · ')}`;
}
text+='\n\nПрофиль и цели редактируются на платформе.';
return [{json:{chat_id:Number(ctx.chat_id),text}}];

const ctx=$items('When Executed by Another Workflow')[0].json;
const n=v=>Number(v||0), r0=v=>Math.round(n(v)), r1=v=>Math.round(n(v)*10)/10;
const tz='Europe/Moscow';
const sum=a=>a.reduce((s,x)=>(s.k+=n(x.kcal),s.p+=n(x.prot),s.f+=n(x.fat),s.c+=n(x.carb),s),{k:0,p:0,f:0,c:0});
const all=$items('CMD DB week meals').map(i=>i.json).filter(r=>r&&r.id&&r.deleted!==true);
const days=[];
for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()-i);days.push(new Intl.DateTimeFormat('sv-SE',{timeZone:tz}).format(d));}
const rows=all.filter(r=>days.includes(String(r.eaten_day||'').slice(0,10)));
const by={}; for(const r of rows)(by[String(r.eaten_day).slice(0,10)]??=[]).push(r);
function sessions(a){const s=[...a].sort((x,y)=>new Date(x.eaten_at)-new Date(y.eaten_at)),o=[];for(const x of s){const p=o.at(-1),t=+new Date(x.eaten_at);if(p&&t-(+new Date(p.at))<=720000){p.rows.push(x);p.at=x.eaten_at}else o.push({at:x.eaten_at,rows:[x]})}return o}
const active=Object.keys(by).length, T=sum(rows), meals=Object.values(by).reduce((a,rs)=>a+sessions(rs).length,0);
let text='';
if(ctx.command==='progress'){
  text=`📈 *Последние 7 дней*\n\nЗаполнено: *${active} из 7 дней*\nСреднее: *${active?r0(T.k/active):0} ккал/день*\n🥩 Белок: *${active?r1(T.p/active):0} г/день*\n🍽 Приёмов: *${meals}*`;
  if(active<4) text+='\n\nДля более точной динамики стоит заполнить ещё несколько дней.';
}else{
  const listed=days.filter(d=>by[d]).slice(0,3);
  text='📅 *История*\n\n'+(listed.length?listed.map(d=>{
    const dt=new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long'}).format(new Date(d+'T12:00:00'));
    return `${dt}\n${r0(sum(by[d]).k)} ккал · ${sessions(by[d]).length} приём.`;
  }).join('\n\n'):'Записей пока нет.');
  if(Object.keys(by).length>3) text+='\n\nПолная история доступна на платформе.';
}
return [{json:{chat_id:Number(ctx.chat_id),text}}];

