const ctx=$items('When Executed by Another Workflow')[0].json;
const n=v=>Number(v||0),r0=v=>Math.round(n(v)),r1=v=>Math.round(n(v)*10)/10;
const tz='Europe/Moscow',today=new Intl.DateTimeFormat('sv-SE',{timeZone:tz}).format(new Date());
const rows=$items('CMD TODAY exact DB').map(i=>i.json)
 .filter(r=>r&&r.id&&r.deleted!==true&&String(r.eaten_day||'').slice(0,10)===today);
const s=$items('CMD DB settings')[0]?.json||{};
const sum=a=>a.reduce((x,r)=>(x.k+=n(r.kcal),x.p+=n(r.prot),x.f+=n(r.fat),x.c+=n(r.carb),x),{k:0,p:0,f:0,c:0});
const T=sum(rows),kt=n(s.kcal_target),pt=n(s.protein_target),ft=n(s.fat_target),ct=n(s.carb_target);
const pct=(v,t)=>t?Math.round(v/t*100):0;

let text=`🌙 *Итоги дня*\n\n🔥 ${r0(T.k)}${kt?` / ${r0(kt)} ккал · ${pct(T.k,kt)}%`:' ккал'}\n🥩 Б ${r1(T.p)}${pt?` / ${r1(pt)} г · ${pct(T.p,pt)}%`:''}\n🥑 Ж ${r1(T.f)}${ft?` / ${r1(ft)} г · ${pct(T.f,ft)}%`:''}\n🍚 У ${r1(T.c)}${ct?` / ${r1(ct)} г · ${pct(T.c,ct)}%`:''}`;

const notes=[];
if(!rows.length) notes.push('Сегодня пока нет записей питания.');
if(kt&&rows.length){
 const d=T.k-kt;
 if(Math.abs(d)<=kt*.08)notes.push('✅ Калорийность близка к дневной цели.');
 else if(d>0)notes.push(`⚠️ Выше цели примерно на ${r0(d)} ккал.`);
 else notes.push(`До дневной цели не добрали примерно ${r0(-d)} ккал.`);
}
if(pt&&rows.length){
 const d=pt-T.p;
 if(d<=0)notes.push('✅ Белок закрыт.');
 else if(d<=15)notes.push(`Белок почти закрыт — осталось около ${r0(d)} г.`);
 else notes.push(`🥩 Белка недобрано около ${r0(d)} г.`);
}
if(ft&&T.f>ft*1.15)notes.push('Жиры заметно выше целевого уровня.');
if(notes.length)text+='\n\n*Оценка*\n'+notes.slice(0,4).map(x=>'• '+x).join('\n');

return [{json:{chat_id:Number(ctx.chat_id),text}}];

const ctx=$items('When Executed by Another Workflow')[0].json;
const tz='Europe/Moscow';
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:tz}).format(new Date());
const rows=$items('CMD TODAY exact DB').map(i=>i.json)
 .filter(r=>r&&r.id&&r.deleted!==true&&String(r.eaten_day||'').slice(0,10)===today);
const st=$items('CMD DB settings')[0]?.json||{};
const p=$items('CMD DB profile')[0]?.json||{};

const n=v=>Number(v||0),r=v=>Math.round(n(v)*10)/10;
const sum=rows.reduce((s,x)=>(s.k+=n(x.kcal),s.p+=n(x.prot),s.f+=n(x.fat),s.c+=n(x.carb),s),{k:0,p:0,f:0,c:0});
const kt=n(st.kcal_target),pt=n(st.protein_target),ft=n(st.fat_target),ct=n(st.carb_target);

function age(v){
 if(!v)return null;
 const b=new Date(v),now=new Date();
 if(Number.isNaN(b.getTime()))return null;
 let a=now.getFullYear()-b.getFullYear();
 const m=now.getMonth()-b.getMonth();
 if(m<0||(m===0&&now.getDate()<b.getDate()))a--;
 return a>0&&a<120?a:null;
}

const payload={
 client_profile:{
   first_name:String(p.first_name||''),
   sex:String(st.sex||''),
   age:age(st.birth_date),
   height_cm:n(st.height_cm)||null,
   current_weight_kg:n(st.current_weight_kg)||null,
   target_weight_kg:n(st.target_weight_kg)||null,
   goal:String(st.goal||'не указана'),
   timezone:String(st.timezone||tz)
 },
 targets:{
   kcal:kt||null,
   protein_g:pt||null,
   fat_g:ft||null,
   carbs_g:ct||null
 },
 today:{
   time:new Intl.DateTimeFormat('ru-RU',{timeZone:tz,hour:'2-digit',minute:'2-digit'}).format(new Date()),
   eaten:{kcal:r(sum.k),protein_g:r(sum.p),fat_g:r(sum.f),carbs_g:r(sum.c)},
   remaining:{
     kcal:kt?Math.max(0,r(kt-sum.k)):null,
     protein_g:pt?Math.max(0,r(pt-sum.p)):null,
     fat_g:ft?Math.max(0,r(ft-sum.f)):null,
     carbs_g:ct?Math.max(0,r(ct-sum.c)):null
   },
   exceeded:{
     kcal:kt?Math.max(0,r(sum.k-kt)):0,
     protein_g:pt?Math.max(0,r(sum.p-pt)):0,
     fat_g:ft?Math.max(0,r(sum.f-ft)):0,
     carbs_g:ct?Math.max(0,r(sum.c-ct)):0
   },
   foods:rows.slice(-12).map(x=>({
     dish:String(x.dish||''),grams:n(x.grams)||null,kcal:r(x.kcal),
     protein_g:r(x.prot),fat_g:r(x.fat),carbs_g:r(x.carb)
   }))
 }
};
return [{json:{chat_id:Number(ctx.chat_id),prompt_data:JSON.stringify(payload,null,2)}}];

const ctx=$items('When Executed by Another Workflow')[0].json;
const j=$json||{};
let text='';

const candidates=[
  j.output_text,
  j.output,
  j.text,
  j.content,
  j.message?.content,
  j.choices?.[0]?.message?.content,
  j.response?.output_text
];
for(const x of candidates){
  if(typeof x==='string'&&x.trim()){text=x.trim();break}
  if(Array.isArray(x)){
    const s=x.map(v=>typeof v==='string'?v:(v?.text||v?.content||'')).filter(Boolean).join('\n').trim();
    if(s){text=s;break}
  }
}
if(!text){
  text='🍽 *Что съесть дальше*\n\nНе удалось сформировать персональную рекомендацию. Попробуй ещё раз через несколько секунд.';
}
return [{json:{chat_id:Number(ctx.chat_id),text}}];
